"use strict";(self.webpackChunklifewell_docs=self.webpackChunklifewell_docs||[]).push([["4297"],{63195(e){e.exports=JSON.parse('{"tag":{"label":"concepts","permalink":"/tags/concepts","allTagsPath":"/tags","count":8,"items":[{"id":"concepts/appearance","title":"Appearance","description":"One icon, one panel, nine settings \u2014 theme, colour, corner radius, density, text size, typeface, surface style, motion and pointer. Applied before the first paint.","permalink":"/concepts/appearance"},{"id":"concepts/architecture","title":"Architecture","description":"A static single-page app over Postgres, with edge functions only where the browser must not hold something. What runs where, and why there is no server of our own.","permalink":"/concepts/architecture"},{"id":"concepts/language-and-units","title":"Language and units","description":"English is the only language today, and the app is built so a second one is a single new file. Units are a preference, not a consequence of your language.","permalink":"/concepts/language-and-units"},{"id":"concepts/offline-and-sync","title":"Offline and sync","description":"Entries are written locally first and sync when there is a connection. What works with no signal, what does not, and how the app says which.","permalink":"/concepts/offline-and-sync"},{"id":"concepts/privacy-and-security","title":"Privacy and security","description":"What leaves your device and what does not \u2014 sign-in without a password, per-row database rules, scrubbed analytics, the contacts permission, identity card pictures, and the claims LifeWell deliberately does not make.","permalink":"/concepts/privacy-and-security"},{"id":"concepts/data-model","title":"The data model","description":"How LifeWell stores a life \u2014 one table per idea, one store behind every tracker, and the three decisions that shape everything above them.","permalink":"/concepts/data-model"},{"id":"domains/overview","title":"The seven areas","description":"LifeWell is organised into seven areas around You \u2014 people first, then memories, everyday and sharing, with health, mind and life stages around them. Six can be switched off without deleting anything; Sharing cannot.","permalink":"/domains/overview"},{"id":"your-data/where-it-lives","title":"Where your record lives","description":"Written on your device first, synced to a Postgres database with per-row rules, with photos in your own Google Drive. What that means when you go offline, disconnect, or leave.","permalink":"/your-data/where-it-lives"}],"unlisted":false}}')}}]);